"""Run once from the backend folder:  python apply_phase5.py
Creates the Phase 5 (Discord) files and patches 3 existing files. Safe to run twice."""
import base64, sys
from pathlib import Path

if not Path("app/main.py").exists():
    sys.exit("Run this from the backend folder (the one that has app/ and workflow/).")

FILES = {
    'integrations/discord.py': "",
    'app/routers/discord.py': "",
    'scripts/test_discord_embed.py': "",
    'tests/test_discord.py': "",
    'tests/test_discord_trigger.py': "",
}

for path, b64 in FILES.items():
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
    print("written ", path)


def patch(path, old, new, marker):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    if marker in text:
        print("already patched", path)
        return
    if old not in text:
        sys.exit(f"Could not patch {path}: expected text not found. Send me this file.")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")
    print("patched ", path)


patch("app/config.py", '    discord_webhook_url: str = ""',
      '    discord_webhook_url: str = ""\n    dashboard_url: str = ""', "dashboard_url")
patch("workflow/runner.py", "from app.config import settings\n",
      "from app.config import settings\nfrom integrations.discord import maybe_alert\n", "maybe_alert")
patch("workflow/runner.py",
      "        workflow_repo.save_workflow_result(db, ticket_id, status, ticket_fields(final), business_id)\n        return WorkflowOutcome(\n            ticket_id=ticket_id, status=status,",
      "        workflow_repo.save_workflow_result(db, ticket_id, status, ticket_fields(final), business_id)\n        maybe_alert(db, ticket_id, business_id)  # never raises; the ticket is already saved\n        return WorkflowOutcome(\n            ticket_id=ticket_id, status=status,",
      "maybe_alert(db")
patch("app/main.py", "import contact, internal, reprocess, tickets", "import contact, discord, internal, reprocess, tickets", "import contact, discord")
patch("app/main.py", "app.include_router(internal.router, dependencies=[Depends(require_api_key)])",
      "app.include_router(internal.router, dependencies=[Depends(require_api_key)])\napp.include_router(discord.router, dependencies=[Depends(require_api_key)])", "discord.router")

conf = Path("tests/conftest.py")
if "no_real_discord" not in conf.read_text(encoding="utf-8"):
    with conf.open("a", encoding="utf-8") as f:
        f.write('''

@pytest.fixture(autouse=True)
def no_real_discord(monkeypatch):
    """Tests must never post to the real Discord channel."""
    monkeypatch.setattr(settings, "discord_webhook_url", "")
''')
    print("patched  tests/conftest.py")
print("\nDone. Now run: python -m pytest   and   python scripts\\test_discord_embed.py")
